-- Registered-member offer approved 18 November 2026. Preserve plan IDs, account links and contract snapshots; no automated quota enforcement.
begin;
lock table public.crm_plans in share row exclusive mode;
do $guard$ begin
  if not exists(select 1 from public.crm_plans p where to_jsonb(p) @> '{"name":"أساس","description":"بداية مرتّبة لناديك","pricing_type":"fixed","annual_fee_cents":180000,"setup_fee_cents":0,"features":["فرع واحد","إدارة الأعضاء والاشتراكات","التجديد والتجميد ومتابعة الحضور","نقاط البيع وورديات الصندوق","الفواتير والتحصيل والمرتجعات","صلاحيات فريق العمل","التقارير الأساسية"],"active":true,"sort_order":1,"revision":1}'::jsonb) then raise exception 'Pricing catalog changed since inspection; review before applying'; end if;
  if not exists(select 1 from public.crm_plans p where to_jsonb(p) @> '{"name":"تشغيل","description":"للحجوزات والتدريب اليومي","pricing_type":"fixed","annual_fee_cents":330000,"setup_fee_cents":0,"features":["فرع واحد","إدارة الأعضاء والاشتراكات","التجديد والتجميد ومتابعة الحضور","نقاط البيع وورديات الصندوق","الفواتير والتحصيل والمرتجعات","صلاحيات فريق العمل","التقارير الأساسية","حجوزات الملاعب والحصص","مواعيد التدريب الشخصي","إدارة المدربين والقياسات","الخطط والبرامج التدريبية","جداول ودوام الموظفين"],"active":true,"sort_order":2,"revision":1}'::jsonb) then raise exception 'Pricing catalog changed since inspection; review before applying'; end if;
  if not exists(select 1 from public.crm_plans p where to_jsonb(p) @> '{"name":"متكاملة","description":"لربط المبيعات والمخزون والوجبات","pricing_type":"fixed","annual_fee_cents":420000,"setup_fee_cents":0,"features":["فرع واحد","إدارة الأعضاء والاشتراكات","التجديد والتجميد ومتابعة الحضور","نقاط البيع وورديات الصندوق","الفواتير والتحصيل والمرتجعات","صلاحيات فريق العمل","التقارير الأساسية","حجوزات الملاعب والحصص","مواعيد التدريب الشخصي","إدارة المدربين والقياسات","الخطط والبرامج التدريبية","جداول ودوام الموظفين","المنتجات ومخزونها والمرتجعات","المطبخ وقوائم الوجبات اليومية","اشتراكات الوجبات وصرفها","تقارير المبيعات والتشغيل"],"active":true,"sort_order":3,"revision":0}'::jsonb) then raise exception 'Pricing catalog changed since inspection; review before applying'; end if;
  if not exists(select 1 from public.crm_plans p where to_jsonb(p) @> '{"name":"توسّع","description":"منظومة تنمو مع طموحك","pricing_type":"fixed","annual_fee_cents":660000,"setup_fee_cents":0,"features":["فرعان","إدارة الأعضاء والاشتراكات","التجديد والتجميد ومتابعة الحضور","نقاط البيع وورديات الصندوق","الفواتير والتحصيل والمرتجعات","صلاحيات فريق العمل","التقارير الأساسية","حجوزات الملاعب والحصص","مواعيد التدريب الشخصي","إدارة المدربين والقياسات","الخطط والبرامج التدريبية","جداول ودوام الموظفين","المنتجات ومخزونها والمرتجعات","المطبخ وقوائم الوجبات اليومية","اشتراكات الوجبات وصرفها","تقارير المبيعات والتشغيل","إدارة مركزية للفروع","صلاحيات وتشغيل حسب الفرع","تقارير مجمّعة لمتابعة الأداء"],"active":true,"sort_order":4,"revision":1}'::jsonb) then raise exception 'Pricing catalog changed since inspection; review before applying'; end if;
  if not exists(select 1 from public.crm_plans p where to_jsonb(p) @> '{"name":"شراكة تقنية","description":"لثلاثة فروع فأكثر أو احتياجات تقنية خاصة، بعرض سعر مخصص دون اشتراط تطوير.","pricing_type":"custom","annual_fee_cents":null,"setup_fee_cents":0,"features":["اشتراك المنصة لثلاثة فروع فأكثر أو احتياج تقني خاص","نقاط البيع وورديات الصندوق ضمن نطاق المنصة","تحديد وظائف المنصة والتهيئة ونقل البيانات والتدريب والدعم في العرض","يمكن أن يقتصر الاتفاق على اشتراك المنصة للفروع","التطبيقات والتكاملات والتطوير اختيارية وتُسعّر منفصلة","تحديد الأجهزة ورسوم الأطراف الأخرى والصيانة بشكل مستقل"],"active":true,"sort_order":5,"revision":1}'::jsonb) then raise exception 'Pricing catalog changed since inspection; review before applying'; end if;
  if exists(select 1 from public.crm_plans where lower(btrim(name)) in ('نمو','احتراف')) then raise exception 'New plan name already exists; review before applying'; end if;
end $guard$;
update public.crm_plans set name='أساس',description='بداية مرتّبة لناديك',annual_fee_cents=180000,features=array['فرع واحد','حتى ١٬٠٠٠ عضو مسجّل','الأعضاء والاشتراكات والتجديد والتجميد','الحضور وحجوزات الملاعب والحصص','التدريب الشخصي والمدربون والقياسات','الخطط والبرامج التدريبية','نقاط البيع وورديات الصندوق','الفواتير والتحصيل والمرتجعات','جداول ودوام الموظفين','صلاحيات الفريق والتقارير','يشمل العدد كل عضو مسجّل لدى المؤسسة، سواء كان اشتراكه ساريًا أو مجمّدًا أو منتهيًا، بما في ذلك ملفات الأعضاء القديمة. يُحسب العضو مرة واحدة مهما تعددت اشتراكاته أو الفروع التي يستخدمها؛ العملاء المحتملون قبل تسجيلهم كأعضاء خارج العدد.','عند تجاوز حد الباقة نراجع معك الترقية ونمنح مهلة متفقًا عليها لاستكمالها؛ لا يتوقف التشغيل فورًا بسبب التجاوز.','المنتجات والمخزون والمطبخ والوجبات إضافات اختيارية بعرض مستقل']::text[],sort_order=1 where name='أساس';
update public.crm_plans set name='نمو',description='مساحة أكبر لنمو عضويتك',annual_fee_cents=330000,features=array['فرع واحد','حتى ٥٬٠٠٠ عضو مسجّل','الأعضاء والاشتراكات والتجديد والتجميد','الحضور وحجوزات الملاعب والحصص','التدريب الشخصي والمدربون والقياسات','الخطط والبرامج التدريبية','نقاط البيع وورديات الصندوق','الفواتير والتحصيل والمرتجعات','جداول ودوام الموظفين','صلاحيات الفريق والتقارير','يشمل العدد كل عضو مسجّل لدى المؤسسة، سواء كان اشتراكه ساريًا أو مجمّدًا أو منتهيًا، بما في ذلك ملفات الأعضاء القديمة. يُحسب العضو مرة واحدة مهما تعددت اشتراكاته أو الفروع التي يستخدمها؛ العملاء المحتملون قبل تسجيلهم كأعضاء خارج العدد.','عند تجاوز حد الباقة نراجع معك الترقية ونمنح مهلة متفقًا عليها لاستكمالها؛ لا يتوقف التشغيل فورًا بسبب التجاوز.','المنتجات والمخزون والمطبخ والوجبات إضافات اختيارية بعرض مستقل']::text[],sort_order=2 where name='تشغيل';
update public.crm_plans set name='احتراف',description='للمؤسسة ذات العضوية الأكبر',annual_fee_cents=420000,features=array['فرع واحد','حتى ١٠٬٠٠٠ عضو مسجّل','الأعضاء والاشتراكات والتجديد والتجميد','الحضور وحجوزات الملاعب والحصص','التدريب الشخصي والمدربون والقياسات','الخطط والبرامج التدريبية','نقاط البيع وورديات الصندوق','الفواتير والتحصيل والمرتجعات','جداول ودوام الموظفين','صلاحيات الفريق والتقارير','يشمل العدد كل عضو مسجّل لدى المؤسسة، سواء كان اشتراكه ساريًا أو مجمّدًا أو منتهيًا، بما في ذلك ملفات الأعضاء القديمة. يُحسب العضو مرة واحدة مهما تعددت اشتراكاته أو الفروع التي يستخدمها؛ العملاء المحتملون قبل تسجيلهم كأعضاء خارج العدد.','عند تجاوز حد الباقة نراجع معك الترقية ونمنح مهلة متفقًا عليها لاستكمالها؛ لا يتوقف التشغيل فورًا بسبب التجاوز.','المنتجات والمخزون والمطبخ والوجبات إضافات اختيارية بعرض مستقل']::text[],sort_order=3 where name='متكاملة';
update public.crm_plans set name='توسّع',description='منظومة تنمو مع طموحك',annual_fee_cents=660000,features=array['فرعان','حتى ١٠٬٠٠٠ عضو مسجّل إجمالًا عبر الفرعين','الأعضاء والاشتراكات والتجديد والتجميد','الحضور وحجوزات الملاعب والحصص','التدريب الشخصي والمدربون والقياسات','الخطط والبرامج التدريبية','نقاط البيع وورديات الصندوق','الفواتير والتحصيل والمرتجعات','جداول ودوام الموظفين','صلاحيات الفريق والتقارير','إدارة مركزية للفروع','صلاحيات وتشغيل حسب الفرع','تقارير مجمّعة لمتابعة الأداء','يشمل العدد كل عضو مسجّل لدى المؤسسة، سواء كان اشتراكه ساريًا أو مجمّدًا أو منتهيًا، بما في ذلك ملفات الأعضاء القديمة. يُحسب العضو مرة واحدة مهما تعددت اشتراكاته أو الفروع التي يستخدمها؛ العملاء المحتملون قبل تسجيلهم كأعضاء خارج العدد.','عند تجاوز حد الباقة نراجع معك الترقية ونمنح مهلة متفقًا عليها لاستكمالها؛ لا يتوقف التشغيل فورًا بسبب التجاوز.','المنتجات والمخزون والمطبخ والوجبات إضافات اختيارية بعرض مستقل']::text[],sort_order=4 where name='توسّع';
update public.crm_plans set description='لتجاوز حدود الأعضاء المسجلين أو لثلاثة فروع فأكثر أو احتياج تقني خاص، دون اشتراط تطوير.',features=array['عدد الأعضاء المسجلين والفروع ونطاق المنصة حسب الاتفاق','يشمل العدد كل عضو مسجّل لدى المؤسسة، سواء كان اشتراكه ساريًا أو مجمّدًا أو منتهيًا، بما في ذلك ملفات الأعضاء القديمة. يُحسب العضو مرة واحدة مهما تعددت اشتراكاته أو الفروع التي يستخدمها؛ العملاء المحتملون قبل تسجيلهم كأعضاء خارج العدد.','يمكن أن يقتصر الاتفاق على اشتراك المنصة والتهيئة والدعم','المنتجات والمخزون والمطبخ والوجبات إضافات اختيارية بعرض مستقل','التطبيقات والبوابات المتوافقة والتكاملات والتطوير اختيارية وتُسعّر منفصلة','تحديد الأجهزة ورسوم الأطراف الأخرى والصيانة بشكل مستقل']::text[],sort_order=5 where name='شراكة تقنية';
commit;
